add_filter( 'the_content', 'perfectpixel_post_share_buttons', 30 );

function perfectpixel_post_share_buttons( $content ) {
	$types = array_filter( array_map( 'trim', explode( ',', '{{post_share_post_types}}' ) ) );
	if ( ! is_singular( $types ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	$url   = rawurlencode( get_permalink() );
	$title = rawurlencode( wp_strip_all_tags( get_the_title() ) );
	$color = sanitize_hex_color( '{{post_share_color}}' );
	$color = $color ? $color : '#1d2327';
	$links = array(
		'Facebook' => 'https://www.facebook.com/sharer/sharer.php?u=' . $url,
		'X'        => 'https://twitter.com/intent/tweet?url=' . $url . '&text=' . $title,
		'LinkedIn' => 'https://www.linkedin.com/sharing/share-offsite/?url=' . $url,
		'WhatsApp' => 'https://wa.me/?text=' . $title . '%20' . $url,
		'Email'    => 'mailto:?subject=' . $title . '&body=' . $url,
	);
	$html = '<div class="perfectpixel-post-share" style="display:flex;flex-wrap:wrap;align-items:center;gap:.5em;margin:2em 0 0"><span>' . esc_html( '{{post_share_label}}' ) . '</span>';
	foreach ( $links as $name => $href ) {
		$html .= sprintf(
			'<a href="%1$s"%2$s style="display:inline-block;padding:.35em .8em;border-radius:3px;background:%3$s;color:#fff;text-decoration:none;font-size:.9em">%4$s</a>',
			esc_url( $href, array( 'https', 'mailto' ) ),
			'Email' === $name ? '' : ' target="_blank" rel="noopener noreferrer nofollow"',
			esc_attr( $color ),
			esc_html( $name )
		);
	}
	return $content . $html . '</div>';
}
